<?php
namespace VPM\Booking;
if ( ! defined( 'ABSPATH' ) ) { exit; }
final class Portal {
    public static function handle( int $partner, array $d ): void {
        Tenants::authorize($partner,true); $action=$d['portal_action']??'';
        if($action==='message')Broker::submit($partner,(string)($d['reference']??''),(string)($d['body']??''),(string)($d['request_key']??''));
        elseif($action==='conditions')Conditions::save($partner,$d);
        elseif($action==='delay_review'){$r=DB::row('delays','id',Operations::number($d['id']??'',1));$b=$r?DB::row('bookings','id',$r['booking_id']):array();Config::require($b&&(int)$b['partner_id']===$partner&&!empty($d['acknowledged']),'portal_forbidden');Conditions::resolve((int)$r['id']);}
        elseif(in_array($action,array('no_show','delay'),true)){$b=Core::booking((string)($d['reference']??''));Config::require((int)$b['partner_id']===$partner,'portal_forbidden');if($action==='no_show'){Config::require(!empty($d['acknowledged']),'no_show_confirmation_required');Conditions::no_show($b['public_id']);}else{$q=Core::snapshot($b);$instant=PublicApi::instant((string)($d['collection']??''),$q['travel']['timezone'],'return',(string)($d['offset']??''));Conditions::delay($b['public_id'],$instant,(string)($d['request_key']??''),(string)($d['leg']??'return'));}}
        elseif($action==='inquiry_done'){global $wpdb;$id=Operations::number($d['id']??'',1);$owner=$wpdb->get_var($wpdb->prepare('SELECT b.partner_id FROM '.DB::table('inquiries').' i INNER JOIN '.DB::table('bookings').' b ON b.id=i.booking_id WHERE i.id=%d',$id));Config::require((int)$owner===$partner,'portal_forbidden');DB::update('inquiries',array('state'=>'completed'),array('id'=>$id));Operations::audit('partner.inquiry_completed','inquiry',$id);}
        elseif($action==='services')Commerce::save($partner,$d);
        elseif($action==='capacity')Adapters::save_capacity($partner,$d);
        elseif($action==='logistics')Logistics::save($partner,$d);
        elseif($action==='logistics_refresh'){ $b=Core::booking((string)($d['reference']??''));Config::require((int)$b['partner_id']===$partner,'portal_forbidden');Logistics::refresh($b['public_id']); }
        elseif($action==='connection')Adapters::configure($partner,$d);
        elseif($action==='rate')Adapters::save_rate($partner,$d);
        elseif($action==='product'){ $d['partner_id']=(string)$partner; Products::save_template($d); }
        elseif($action==='retry'){ $job=DB::row('fulfilment','id',Operations::number($d['id']??'',1));$b=$job?DB::row('bookings','id',$job['booking_id']):array();Config::require($b&&(int)$b['partner_id']===$partner,'portal_forbidden');Flow::retry((int)$job['id']); }
        elseif($action==='cancel'){ $b=Core::booking((string)($d['reference']??''));Config::require((int)$b['partner_id']===$partner,'portal_forbidden'); Flow::cancel_request($b['public_id']);Operations::audit('portal.cancel_requested','booking',(int)$b['id']); }
        else throw new \RuntimeException('invalid_portal_action');
    }
    public static function register(): void {
        add_action('init',function(){add_role('vpm_partner','VPM Partner',array('read'=>true));add_role('vpm_platform_staff','VPM Einrichtungsteam',array('read'=>true));});
        add_action('template_redirect',array(self::class,'landing'),1);
        add_action('rest_api_init',function(){
            foreach(array('stats','bookings')as $resource) register_rest_route('vpm-booking/v1','/portal/(?P<partner>\d+)/'.$resource,array('methods'=>'GET','permission_callback'=>'is_user_logged_in','callback'=>function($r)use($resource){try{$id=(int)$r['partner'];return $resource==='stats'?Tenants::stats($id):Tenants::bookings($id,max(1,(int)$r->get_param('page')));}catch(\Throwable $e){return new \WP_Error('portal_forbidden','portal_forbidden',array('status'=>403));}}));
            register_rest_route('vpm-booking/v1','/portal/(?P<partner>\\d+)/configuration',array('methods'=>'POST','permission_callback'=>'is_user_logged_in','callback'=>function($r){try{$d=$r->get_json_params();Config::require(is_array($d)&&strlen($r->get_body())<50000&&in_array($d['portal_action']??'',array('services','capacity','rate','logistics','conditions'),true),'invalid_configuration');self::handle((int)$r['partner'],$d);return array('saved'=>true);}catch(\Throwable $e){return new \WP_Error('configuration_rejected','configuration_rejected',array('status'=>403));}}));
            register_rest_route('vpm-booking/v1','/demo/complete',array('methods'=>'POST','permission_callback'=>'is_user_logged_in','callback'=>function($r){try{return Flow::demo_complete((string)$r->get_param('reference'));}catch(\Throwable $e){return new \WP_Error('demo_unavailable','demo_unavailable',array('status'=>403));}}));
        });
    }
    private static function form( string $action,int $partner ):void{echo '<form method="post">';wp_nonce_field('vpm_partner_portal');echo '<input type="hidden" name="portal_action" value="'.esc_attr($action).'"><input type="hidden" name="partner" value="'.$partner.'">';}
    private static function field(string $name,string $label,$value='',string $type='text'):void{echo '<label>'.esc_html($label).'<input type="'.esc_attr($type).'" name="'.esc_attr($name).'" value="'.esc_attr((string)$value).'" autocomplete="'.($type==='password'?'new-password':'off').'"></label>';}
    private static function stats(array $stats):void{
        $labels=array('enquiries'=>'Erfasste Anfragen','customers'=>'Eindeutige Kunden-E-Mails','checkouts'=>'Gestartete Zahlungen','paid'=>'Bezahlte Vorgänge (inkl. späterer Erstattung)','paid_checkout_ratio_percent'=>'Zahlungserfolg innerhalb erfasster Checkouts (%)','partner_entitlement_cents'=>'Partneranspruch laut Journal','commission_cents'=>'Provision laut Journal','discount_cost_cents'=>'Rabattkosten nach Erstattungen','net_commission_cents'=>'Provision abzüglich Rabatte (vor Gebühren)','newsletter_confirmed'=>'Bestätigte Newsletter-Abos');echo '<div class="vpm-portal-metrics">';foreach($labels as $key=>$label)if(array_key_exists($key,$stats))echo '<article><strong>'.esc_html($stats[$key]===null?'Noch keine Daten':(str_ends_with($key,'_cents')?number_format($stats[$key]/100,2,',','.').' €':(string)$stats[$key])).'</strong><span>'.esc_html($label).'</span></article>';echo '</div>';
    }
    public static function landing():void{
        if(!isset($_GET['vpm_partner_portal']))return;
        if(!is_user_logged_in()){auth_redirect();exit;}
        nocache_headers();header('X-Robots-Tag: noindex, nofollow, noarchive');header('Referrer-Policy: no-referrer');header('X-Frame-Options: DENY');header("Content-Security-Policy: default-src 'self'; style-src 'self'; script-src 'self'; form-action 'self'; frame-ancestors 'none'; base-uri 'self'");
        $partners=Tenants::partners();$selected=isset($_GET['partner'])&&is_scalar($_GET['partner'])?absint($_GET['partner']):(int)($partners[0]['id']??0);$error='';
        try{if($selected)Tenants::authorize($selected);if(isset($_POST['portal_action'])){check_admin_referer('vpm_partner_portal');$posted=Operations::number(wp_unslash($_POST['partner']??''),1);Portal::handle($posted,wp_unslash($_POST));wp_safe_redirect(add_query_arg(array('vpm_partner_portal'=>1,'partner'=>$posted,'saved'=>1),home_url('/')));exit;}}
        catch(\Throwable $e){status_header(403);$error='Zugriff oder Änderung nicht möglich.';$selected=0;}
        $assets=plugins_url('',dirname(__DIR__).'/vpm-booking-core.php');echo '<!doctype html><html lang="de"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Partnerportal</title><link rel="stylesheet" href="'.esc_url($assets.'/assets/portal.css?ver=0.10.0').'"></head><body><main class="vpm-portal"><header><h1>Partnerportal</h1><a href="'.esc_url(wp_logout_url(home_url('/'))).'">Abmelden</a></header><p>Geschützter Entwicklungsstand. Keine Live-Zahlungen oder unbestätigten Partnerbuchungen als abgeschlossen ausweisen.</p>';
        if($error)echo '<p role="alert">'.esc_html($error).'</p>';if(isset($_GET['saved']))echo '<p role="status">Erfasst. Kundenbezogene Texte benötigen gegebenenfalls Plattformfreigabe.</p>';
        echo '<form method="get"><input type="hidden" name="vpm_partner_portal" value="1"><label>Zugeordneter Partner<select name="partner">';foreach($partners as $p)echo '<option value="'.(int)$p['id'].'" '.selected($selected,(int)$p['id'],false).'>'.esc_html($p['name'].' – '.$p['airport']).'</option>';echo '</select></label><button>Öffnen</button></form>';
        if(current_user_can('manage_options')){
            global $wpdb;echo '<h2>Plattformgesamtübersicht</h2><p>Letzter Worker (UTC): '.esc_html(get_option('vpm_booking_last_worker')?gmdate('Y-m-d H:i:s',(int)get_option('vpm_booking_last_worker')):'Noch kein Lauf nachgewiesen').'</p><p>Partneraufgaben mit Klärungsbedarf: '.(int)$wpdb->get_var('SELECT COUNT(*) FROM '.DB::table('fulfilment')." WHERE status='attention'").'; E-Mail-Aufgaben mit Klärungsbedarf: '.(int)$wpdb->get_var('SELECT COUNT(*) FROM '.DB::table('outbox')." WHERE status='attention'").'</p>';self::stats(Tenants::stats(null));echo '<p>Geldwerte stammen aus dem Buchungsjournal, nicht aus einem bestätigten Bank-/Stripe-Auszahlungsabgleich. Besucher-Conversion ist hier nicht erfasst.</p><h3>Nach Partner</h3><div class="vpm-portal-table"><table><tr><th>Partner</th><th>Anfragen</th><th>Provision nach Rabatten (Cent)</th><th>Rabattkosten (Cent)</th></tr>';
            foreach($partners as $p){$s=Tenants::stats((int)$p['id']);global $wpdb;$ledger=$wpdb->get_results($wpdb->prepare('SELECT l.account,SUM(l.cents) cents FROM '.DB::table('ledger').' l INNER JOIN '.DB::table('bookings').' b ON b.id=l.booking_id WHERE b.partner_id=%d AND NOT EXISTS (SELECT 1 FROM '.DB::table('demo').' d WHERE d.booking_id=b.id) GROUP BY l.account',$p['id']),ARRAY_A);$a=array_column($ledger,'cents','account');echo '<tr><td>'.esc_html($p['name']).'</td><td>'.$s['enquiries'].'</td><td>'.(-(int)($a['commission_revenue']??0)-(int)($a['promotion_expense']??0)).'</td><td>'.(int)($a['promotion_expense']??0).'</td></tr>'; }echo '</table></div>';
        }
        if(!$selected){echo '<p>Kein freigegebener Partnerzugang ausgewählt. Die Plattformverwaltung ordnet Benutzer und Rechte zu.</p></main></body></html>';exit;}
        $role=Tenants::role($selected);$write=in_array($role,array('platform','owner','manager','support'),true);
        echo '<nav class="vpm-portal-nav" aria-label="Partnerverwaltung">';foreach(array('overview'=>'Übersicht','bookings'=>'Buchungen / ausstehende Vorgänge','requests'=>'Stornos & Klärungsfälle','inventory'=>'Stellplätze & Kapazitäten','products'=>'Angebote & Extras','prices'=>'Preisverwaltung','service-times'=>'Servicegebühren & Zeiten','conditions'=>'Storno, Verspätung & Puffer','logistics'=>'Standort & Anreise','notifications'=>'Benachrichtigungen','statistics'=>'Statistiken','connections'=>'Anbindungen & Zugänge')as $anchor=>$label)if($write||in_array($anchor,array('overview','bookings','requests','statistics'),true))echo '<a href="#'.esc_attr($anchor).'">'.esc_html($label).'</a>';echo '</nav><section id="overview">';
        $role=Tenants::role($selected);$write=in_array($role,array('platform','owner','manager','support'),true);echo '<h2>Eigene Partnerübersicht</h2><p>Rolle: '.esc_html(array('owner'=>'Partnerinhaber','manager'=>'Partnermitarbeiter','viewer'=>'Nur Lesen','support'=>'Einrichtungsteam','platform'=>'Plattformverwaltung')[$role]??$role).'. Newsletter-Kontaktlisten und Daten anderer Partner sind hier nicht verfügbar.</p>';echo '<p>Offene Vorgänge unter Buchungen und Stornos prüfen. Änderungen werden protokolliert; Zugriff nur auf zugeordnete Partner.</p></section><section id="statistics"><h2>Eigene Statistiken</h2>';self::stats(Tenants::stats($selected));echo '</section><section id="bookings">';
        $page=isset($_GET['p'])&&is_scalar($_GET['p'])?max(1,absint($_GET['p'])):1;echo '<h2>Buchungen und erfasste Checkouts</h2><div class="vpm-portal-table"><table><tr><th>Referenz / Kontakt</th><th>Status</th><th>Reise / Leistungen</th><th>Partneranspruch vor Erstattung</th><th>Aktion</th></tr>';
        foreach(Tenants::bookings($selected,$page)as $b){$travel=$b['travel'];$items=array_map(function($a){return $a['quantity'].' × '.$a['label'];},$b['selection']['addons']??array());echo '<tr><td>'.esc_html($b['reference']).'<br>'.esc_html($b['email']).'</td><td>'.esc_html($b['state'].' / '.$b['payment_state']).'<br>'.($b['checkout_started']?'Zahlung gestartet':'Kein Zahlungscheckout erfasst').'</td><td>'.esc_html(($travel?wp_date('d.m.Y H:i',$travel['departure_utc'],new \DateTimeZone($travel['timezone'])).' – '.wp_date('d.m.Y H:i',$travel['return_utc'],new \DateTimeZone($travel['timezone'])):'Keine Reisedaten').'; '.implode(', ',$items)).'</td><td>'.esc_html(number_format($b['partner_expected_cents']/100,2,',','.')).' €</td><td>';if($write&&$b['state']==='confirmed'&&in_array($b['payment_state'],array('paid','partially_refunded'),true)){echo '<details><summary>Verspätung / Nichterscheinen</summary>';self::form('delay',$selected);echo '<input type="hidden" name="reference" value="'.esc_attr($b['reference']).'"><input type="hidden" name="request_key" value="'.esc_attr(wp_generate_uuid4()).'">';echo '<label>Verspätung<select name="leg"><option value="return">Fahrzeugabholung / Rückreise</option><option value="arrival">Fahrzeugabgabe / Anreise</option></select></label>';self::field('collection','Neuer voraussichtlicher Zeitpunkt (Flughafenzeit)','','datetime-local');self::field('offset','Nur bei doppelter Uhrzeit: UTC-Offset, z. B. +01:00');echo '<button>Verspätung erfassen und Kapazität prüfen</button></form>';self::form('no_show',$selected);echo '<input type="hidden" name="reference" value="'.esc_attr($b['reference']).'"><label><input type="checkbox" name="acknowledged" required> Tatsächliches Nichterscheinen nach Übergabetermin geprüft; geltende Gebühr anwenden.</label><button>Nichterscheinen bearbeiten</button></form></details>';self::form('logistics_refresh',$selected);echo '<input type="hidden" name="reference" value="'.esc_attr($b['reference']).'"><button>Aktuelle Fahrhinweise an Kunden übermitteln</button></form>';}if($write){echo '<details><summary>Nachricht über die Plattform</summary>';self::form('message',$selected);echo '<input type="hidden" name="reference" value="'.esc_attr($b['reference']).'"><input type="hidden" name="request_key" value="'.esc_attr(wp_generate_uuid4()).'"><label>Nachricht zur Buchung<textarea name="body" required maxlength="2000"></textarea></label><p>Versand erst nach Plattformfreigabe. Keine Werbung, externen Buchungslinks oder Aufforderungen zum Umgehen der Buchung.</p><button>Zur Prüfung einreichen</button></form></details>';self::form('cancel',$selected);echo '<input type="hidden" name="reference" value="'.esc_attr($b['reference']).'"><button>Stornoablauf anfordern</button></form>';}echo '</td></tr>'; }echo '</table></div><p>Seite '.$page.' · <a href="'.esc_url(add_query_arg('p',max(1,$page-1))).'">Zurück</a> · <a href="'.esc_url(add_query_arg('p',$page+1)).'">Weiter</a></p>';
        echo '</section><section id="requests">';global $wpdb;$jobs=$wpdb->get_results($wpdb->prepare('SELECT f.id,f.action,f.status,f.error_code,b.public_id FROM '.DB::table('fulfilment').' f INNER JOIN '.DB::table('bookings').' b ON b.id=f.booking_id WHERE b.partner_id=%d AND f.status<>%s ORDER BY f.id DESC LIMIT 50',$selected,'succeeded'),ARRAY_A);echo '<h2>Klärungsfälle</h2>';foreach($jobs as $j){echo '<p>'.esc_html($j['public_id'].' · '.$j['action'].' · '.$j['status'].' · '.$j['error_code']).'</p>';if($write&&$j['status']==='attention'){self::form('retry',$selected);echo '<input type="hidden" name="id" value="'.(int)$j['id'].'"><button>Nach Klärung erneut prüfen</button></form>';}}
        $requests=$wpdb->get_results($wpdb->prepare('SELECT c.state,c.created_at,b.public_id FROM '.DB::table('changes').' c INNER JOIN '.DB::table('bookings')." b ON b.id=c.booking_id WHERE b.partner_id=%d AND c.kind='cancellation' AND c.state<>'completed' ORDER BY c.id DESC LIMIT 50",$selected),ARRAY_A);echo '<h2>Offene Stornowünsche</h2>';foreach($requests as $r){echo '<p>'.esc_html($r['public_id'].' · '.$r['state']).'</p>';if($write){echo '<details><summary>Nachricht über die Plattform</summary>';self::form('message',$selected);echo '<input type="hidden" name="reference" value="'.esc_attr($b['reference']).'"><input type="hidden" name="request_key" value="'.esc_attr(wp_generate_uuid4()).'"><label>Nachricht zur Buchung<textarea name="body" required maxlength="2000"></textarea></label><p>Versand erst nach Plattformfreigabe. Keine Werbung, externen Buchungslinks oder Aufforderungen zum Umgehen der Buchung.</p><button>Zur Prüfung einreichen</button></form></details>';self::form('cancel',$selected);echo '<input type="hidden" name="reference" value="'.esc_attr($r['public_id']).'"><button>Storno prüfen und ausführen lassen</button></form>';}}
        $delays=$wpdb->get_results($wpdb->prepare('SELECT d.*,b.public_id FROM '.DB::table('delays')." d INNER JOIN ".DB::table('bookings')." b ON b.id=d.booking_id WHERE b.partner_id=%d AND d.needs_review=1 AND b.state<>'cancelled' ORDER BY d.id DESC LIMIT 50",$selected),ARRAY_A);echo '<h2>Verspätungen mit Klärungsbedarf</h2>';if($delays)echo '<p role="alert">Neue Angebote dieses Partners bleiben bis zur Klärung gesperrt. Bei Kapazitätskonflikt zuerst Kapazität korrigieren und Verspätung erneut erfassen; anschließend abschließen.</p>';foreach($delays as $d){echo '<p>'.esc_html($d['public_id'].' · '.$d['leg'].' · '.(json_decode($d['payload'],true)['capacity']??'')).'</p>';if($write){self::form('delay_review',$selected);echo '<input type="hidden" name="id" value="'.(int)$d['id'].'"><label><input type="checkbox" name="acknowledged" required> Service und Kapazität geklärt / bei externer Anbindung vom führenden System bestätigt.</label><button>Klärung bestätigen</button></form>';}}
        $inquiries=$wpdb->get_results($wpdb->prepare('SELECT i.*,b.public_id,b.customer_email FROM '.DB::table('inquiries')." i INNER JOIN ".DB::table('bookings')." b ON b.id=i.booking_id WHERE b.partner_id=%d AND i.state='pending' ORDER BY i.id DESC LIMIT 50",$selected),ARRAY_A);echo '<h2>Kundenanfragen</h2>';foreach($inquiries as $i){$body=Config::open($i['payload']);echo '<article><h3>'.esc_html($i['public_id']).'</h3><p class="vpm-inquiry-message">'.esc_html(current_user_can('manage_options')?$body['message']:Broker::redact($body['message'],$i['customer_email'])).'</p>';if($write){self::form('inquiry_done',$selected);echo '<input type="hidden" name="id" value="'.(int)$i['id'].'"><button>Nach Bearbeitung abschließen</button></form>';}echo '</article>';}echo '</section>';if($write)self::configuration($selected);echo '</main></body></html>';exit;
    }
    private static function logistics(int $partner):void{
        $profile=Logistics::get($partner);global $wpdb;$draft=$wpdb->get_var($wpdb->prepare('SELECT payload FROM '.DB::table('profile_reviews').' WHERE partner_id=%d',$partner));if($draft&&!current_user_can('manage_options')){$profile=Config::open($draft);echo '<p role="status">Ihr Entwurf wartet auf Plattformfreigabe. Die bisherigen freigegebenen Angaben bleiben bis dahin aktiv.</p>';}echo '<section id="logistics"><h2>Standorte, Übergabe und Buchungssupport</h2><p>Sie sind als Partner für die Parkleistung, Buchungsfragen, Rechnungen, Belege und Stornos zuständig. Neue oder geänderte Angaben werden durch die Plattform geprüft. Bis zur Freigabe bleiben die bisherigen Daten aktiv. Kunden-E-Mails laufen über die Plattform; die Supportnummer und die bestätigten Fahrhinweise werden darin verwendet. Karten öffnen erst nach bewusstem Klick, ohne eingebettete Google-Karte.</p>';
        $missing=array();if(empty($profile['support_phone']))$missing[]='Supportnummer';if(empty($profile['booking_email']))$missing[]='Buchungs-E-Mail';if(empty($profile['billing_email']))$missing[]='Rechnungs-E-Mail';$handover=$profile['points']['handover']??array();if(!Logistics::directions($handover))$missing[]='Anfahrtsziel bei Abreise';if($missing)echo '<p role="status">Vor Kundenfreigabe ergänzen: '.esc_html(implode(', ',$missing)).'.</p>';
        self::form('logistics',$partner);self::field('support_phone','Telefonnummer für Buchungsfragen',$profile['support_phone']??'','tel');self::field('booking_email','Interne Partner-E-Mail für Buchungs- und Stornoanfragen',$profile['booking_email']??'','email');self::field('billing_email','Interne Partner-E-Mail für Rechnungen und Belege',$profile['billing_email']??'','email');
        foreach(array('parking'=>'Parkplatz / Stellplatzadresse','handover'=>'Fahrzeugabgabe / Treffpunkt bei Abreise','return'=>'Fahrzeugrückgabe / Ankunft nach der Reise')as $key=>$label){$point=$profile['points'][$key]??array();echo '<fieldset><legend>'.esc_html($label).'</legend>';
            foreach(array('de'=>'Deutsch','en'=>'Englisch')as $lang=>$language){self::field('points['.$key.'][name_'.$lang.']','Bezeichnung '.$language,$point['name_'.$lang]??'');}
            self::field('points['.$key.'][maps_url]','Google-Maps-Link (optional, HTTPS)',$point['maps_url']??'','url');self::field('points['.$key.'][address]','Vollständige Adresse / Terminal und Treffpunkt',$point['address']??'');self::field('points['.$key.'][latitude]','Optionaler Pin: Breitengrad',$point['latitude']??'');self::field('points['.$key.'][longitude]','Optionaler Pin: Längengrad',$point['longitude']??'');
            foreach(array('de'=>'Deutsch','en'=>'Englisch')as $lang=>$language)echo '<label>Fahr- und Übergabehinweise '.esc_html($language).'<textarea name="points['.$key.'][instructions_'.$lang.']">'.esc_textarea($point['instructions_'.$lang]??'').'</textarea></label>';
            if($point){$link=Logistics::directions($point);if($link)echo '<p><a target="_blank" rel="noopener noreferrer" href="'.esc_url($link).'">Route zum hinterlegten Ziel prüfen</a></p>';}
            echo '</fieldset>';
        }
        echo '<p>Vor der Freigabe alle Ziele und Kontaktdaten prüfen. Neue Angaben gelten für neue Buchungen; bestehende Buchungen behalten ihre gespeicherten Informationen.</p><button>Standorte und Kontakte speichern</button></form></section>';
    }
    private static function services(int $partner):void {
        $c=Commerce::get($partner);echo '<section id="service-times"><h2>Servicegebühren und Servicezeiten</h2><p>Valet und Shuttle teilen den Bestand je Stellplatzangebot. Ohne hinterlegte Uhrzeiten ist ein aktivierter Service jederzeit verfügbar. Mit Uhrzeiten: nur eingetragene Wochentage. Format 06:00-23:00, mehrere Bereiche mit Komma; 00:00-00:00 = ganztägig. Übernachtintervalle wie 22:00-06:00 sind möglich.</p><p>Flugzeitprüfung: Abflug minus 3 Stunden und Landung plus 30 Minuten müssen beide passen. Die genauere Übergabezeit steht in der Bestätigungsmail.</p>';self::form('services',$partner);
        self::field('handover_minutes','Übergabe in der Bestätigung: Minuten vor Abflug (120–180)',$c['handover_minutes']??180,'number');
        foreach(array('parking'=>'Nur Parken / Eigenanreise','valet'=>'Valet','shuttle'=>'Shuttle')as $id=>$label){$r=$c['services'][$id]??array();echo '<fieldset><legend>'.esc_html($label).'</legend><label><input type="checkbox" name="services['.$id.'][enabled]" '.checked(isset($c['services'])?isset($c['services'][$id]):$id==='parking',true,false).'> Leistung anbieten</label>';self::field('services['.$id.'][fee_cents]','Servicegebühr (Cent)',$r['fee_cents']??0,'number');echo '<label>Gebührenbasis<select name="services['.$id.'][fee_basis]"><option value="booking" '.selected($r['fee_basis']??'booking','booking',false).'>Einmal pro Buchung</option><option value="leg" '.selected($r['fee_basis']??'','leg',false).'>Je Übergabe und Rückgabe (zweimal)</option></select></label>';
            foreach(array(1=>'Montag',2=>'Dienstag',3=>'Mittwoch',4=>'Donnerstag',5=>'Freitag',6=>'Samstag',7=>'Sonntag')as $day=>$name){$text=array();foreach($r['hours'][$day]??array()as [$a,$z])$text[]=sprintf('%02d:%02d-%02d:%02d',intdiv($a,60),$a%60,intdiv($z,60),$z%60);self::field('services['.$id.'][hours]['.$day.']',$name,implode(', ',$text));}
            foreach(array('night_start'=>'Nachtbeginn','night_end'=>'Nachtende')as $k=>$v){$m=$r[$k]??($k==='night_start'?1320:360);self::field('services['.$id.']['.$k.']',$v,sprintf('%02d:%02d',intdiv($m,60),$m%60),'time');}
            self::field('services['.$id.'][night_arrival_cents]','Nachtzuschlag Abgabe (Cent)',$r['night_arrival_cents']??0,'number');self::field('services['.$id.'][night_return_cents]','Nachtzuschlag Rückgabe (Cent)',$r['night_return_cents']??0,'number');echo '</fieldset>';
        }echo '<button>Services und Zeiten speichern</button></form></section>';
    }
    private static function inventory(int $partner):void {
        echo '<section id="inventory"><h2>Stellplätze & Kapazitäten</h2><p>Ein Angebot bildet einen physischen Pool einer Stellplatzart. Für Valet und Shuttle keinen zweiten Pool anlegen. Ladeplätze sind im Gesamtbestand enthalten. Reservierungen werden für den gesamten Parkplatzzeitraum geprüft und gesperrt; bestätigte Stornos geben sie frei. Weitere externe Verkäufe benötigen eine führende Systemanbindung.</p>';
        global $wpdb;foreach(Products::catalogue()as $key=>$p){if($p['partner_id']!==$partner)continue;$r=$wpdb->get_row($wpdb->prepare('SELECT * FROM '.DB::table('rates').' WHERE partner_id=%d AND product_id=%s',$partner,$key),ARRAY_A);echo '<h3>'.esc_html(Products::label($p['offer']['product_name'])).'</h3>';if(!$r){echo '<p>Zuerst Grundtarif in der Preisverwaltung anlegen.</p>';continue;}self::form('capacity',$partner);echo '<input type="hidden" name="product_id" value="'.esc_attr($key).'">';self::field('capacity','Gesamtkapazität',$r['capacity'],'number');self::field('charging_capacity','Davon mit Ladesäule',$r['charging_capacity']??0,'number');echo '<button>Kapazitäten speichern</button></form>';}echo '</section>';
    }
    private static function tariff_rules(array $rate):void {
        $rules=json_decode($rate['rules']??'',true)?:array();
        foreach(array('seasons'=>'Saison-Tagespreise','durations'=>'Festpreise für genaue Aufenthaltsdauer','discounts'=>'Aufenthaltsrabatte')as $group=>$label){echo '<details><summary>'.esc_html($label).'</summary>';for($i=0;$i<max(3,count($rules[$group]??array())+1);$i++){$r=$rules[$group][$i]??array();$prefix=$group.'['.$i.']';echo '<fieldset><legend>Regel '.($i+1).'</legend><label><input type="checkbox" name="'.$prefix.'[enabled]" '.checked((bool)$r,true,false).'> Verwenden</label>';
            if($group==='seasons'){self::field($prefix.'[start]','Von (einschließlich)',$r['start']??'','date');self::field($prefix.'[end]','Bis (einschließlich)',$r['end']??'','date');self::field($prefix.'[price_cents]','Tagespreis (Cent)',$r['price_cents']??0,'number');}
            elseif($group==='durations'){self::field($prefix.'[days]','Exakt so viele angefangene 24 Stunden',$r['days']??1,'number');self::field($prefix.'[price_cents]','Gesamtparkpreis (Cent)',$r['price_cents']??0,'number');}
            else{self::field($prefix.'[min_days]','Ab Aufenthaltsdauer (Tage)',$r['min_days']??14,'number');echo '<label>Rabattbasis<select name="'.$prefix.'[kind]"><option value="stay" '.selected($r['kind']??'stay','stay',false).'>Gesamter Parkpreis</option><option value="days" '.selected($r['kind']??'','days',false).'>Bestimmte Aufenthaltstage (nur Tagestarif)</option></select></label>';self::field($prefix.'[from_day]','Ab Aufenthaltstag',$r['from_day']??8,'number');self::field($prefix.'[to_day]','Bis Aufenthaltstag',$r['to_day']??14,'number');self::field($prefix.'[bps]','Rabatt: 100 = 1 %, 1000 = 10 %',$r['bps']??500,'number');}echo '</fieldset>';}echo '</details>';
        }
    }
    private static function conditions(int $partner):void {
        $c=Conditions::get($partner);echo '<section id="conditions"><h2>Storno, Verspätung & Puffer</h2><p>Regeln werden je Angebot/Buchung gespeichert. Spätere Änderungen verändern bestehende Buchungen nicht. Stornogebühren beziehen sich auf den tatsächlich gezahlten Betrag nach Gutschein; keine zusätzliche Abbuchung. Der Eingangszeitpunkt des Stornowunsches entscheidet, nicht Ihre spätere Bearbeitung.</p>';self::form('conditions',$partner);echo '<input type="hidden" name="ui_units" value="1">';
        foreach(array('buffer_before_minutes'=>'Bestandspuffer vor Abgabe (Minuten)','buffer_after_minutes'=>'Bestandspuffer nach Abholung (Minuten)','minimum_notice_minutes'=>'Mindestvorlauf für neue Buchungen (Minuten)','minimum_days'=>'Mindestaufenthalt (angefangene 24 Stunden)','maximum_days'=>'Höchstaufenthalt (angefangene 24 Stunden)','delay_grace_minutes'=>'Kulanz bei Verspätung (Minuten)','delay_hourly_cents'=>'Danach je angefangene Stunde (Cent, nur Berechnung zur Partnerprüfung)')as $k=>$label)self::field($k,$label,$c[$k]??($k==='minimum_days'?1:($k==='maximum_days'?181:0)),'number');
        echo '<label><input type="checkbox" name="cancellation_enabled" '.checked(!empty($c['cancellation_enabled']),true,false).'> Stornostaffeln aktivieren</label><p>Schwelle bedeutet: mindestens so viele Stunden vor Übergabe. Die höchste passende Schwelle gilt. Eine letzte Stufe mit 0 Stunden ist erforderlich und gilt auch bei späterem Stornowunsch. Prozentwerte direkt eingeben (50 = 50 %), Festbeträge in Euro.</p>';
        for($i=0;$i<min(12,max(4,count($c['tiers']??array())+1));$i++){$t=$c['tiers'][$i]??array();echo '<fieldset><legend>Stornostufe '.($i+1).'</legend><label><input type="checkbox" name="tiers['.$i.'][enabled]" '.checked((bool)$t,true,false).'> Verwenden</label>';self::field('tiers['.$i.'][hours]','Mindestens Stunden vor Übergabe',$t['hours']??0,'number');self::fee_fields('tiers['.$i.']',$t);echo '</fieldset>';}
        echo '<fieldset><legend>Nichterscheinen</legend><label><input type="checkbox" name="no_show_enabled" '.checked(!empty($c['no_show_enabled']),true,false).'> Eigene No-show-Regel aktivieren</label>';self::fee_fields('no_show',$c['no_show']??array('kind'=>'percent','value'=>10000));echo '<p>Nur durch berechtigten Mitarbeiter nach Prüfung des tatsächlichen Nichterscheinens; kein automatischer No-show anhand einer Uhrzeit.</p></fieldset><button>Bedingungen speichern</button></form></section>';
    }
    private static function fee_fields(string $prefix,array $r):void {echo '<label>Gebührenart<select name="'.esc_attr($prefix.'[kind]').'"><option value="percent" '.selected($r['kind']??'percent','percent',false).'>Prozent</option><option value="fixed" '.selected($r['kind']??'','fixed',false).'>Festbetrag in Euro</option></select></label>';self::field($prefix.'[value]','Gebührenwert (Prozent oder Euro)',number_format(($r['value']??0)/100,2,',',''));}
    private static function configuration(int $partner):void{
        self::logistics($partner);self::services($partner);self::conditions($partner);self::inventory($partner);echo '<section id="notifications"><h2>Benachrichtigungen</h2><p>Neue unbezahlte Anfrage, Zahlung, bestätigte Buchung, Stornowunsch und bestätigter Storno werden getrennt für die interne Buchungs-E-Mail vorbereitet. Rechnungsaufgaben gehen an die Rechnungs-E-Mail. Empfänger pflegen Sie unter Standort & Anreise. Kunden erhalten die Anfahrtshinweise mit der Bestätigung über die Plattformadresse.</p><p>Versanddienst noch nicht angeschlossen; dies ist keine Zustellbestätigung. Kundenanfragen aus dem geschützten Buchungszugang erscheinen unter Stornos & Klärungsfälle. Antworten erfolgen zunächst über den vereinbarten Supportweg; ein Antworteditor ist noch nicht angeschlossen.</p></section><section id="connections">';
        $c=Adapters::connection($partner); if(!empty($c['last_error']))echo '<p role="alert">Letzte Anbieterabfrage fehlgeschlagen: '.esc_html($c['last_error']).'</p>';echo '<h2>Systemanbindung oder Eigenverwaltung</h2>';self::form('connection',$partner);echo '<label>Betriebsart<select name="mode">';foreach(array('disabled'=>'Noch nicht aktiv','manual'=>'Preise und Kapazitäten selbst verwalten','external'=>'Installierten Systemadapter verwenden')as $k=>$v)echo '<option value="'.$k.'" '.selected($c['mode']??'disabled',$k,false).'>'.esc_html($v).'</option>';echo '</select></label><label>Installierter Adapter<select name="adapter"><option value="">Keiner</option>';foreach(Adapters::registry()as $id=>$driver)echo '<option value="'.esc_attr($id).'" '.selected($c['adapter']??'',$id,false).'>'.esc_html($id).'</option>';echo '</select></label>';self::field('api_key','Neuen API-Schlüssel setzen; leer lässt denselben Adapter unverändert','','password');echo '<label><input type="checkbox" name="clear_credentials"> Gespeicherte Zugangsdaten entfernen</label><label><input type="checkbox" name="assistance" '.checked(!empty($c['assistance']),true,false).'> Einrichtung durch das Plattformteam anfragen (Preis separat vereinbaren)</label><p>Zugangsdaten werden verschlüsselt gespeichert und niemals hier angezeigt. Speichern bestätigt noch keine funktionierende Verbindung.</p><button>Verbindungseinstellungen speichern</button></form>';
        echo '</section><section id="products">';$catalogue=Products::catalogue();$id=is_string($_GET['product']??null)?sanitize_key($_GET['product']):'';$record=$catalogue[$id]??array();if($record&&$record['partner_id']!==$partner){$record=array();$id='';}$o=$record['offer']??array();
        echo '<h2>Eigene Angebote und Extras</h2>';self::form('product',$partner);echo '<input type="hidden" name="product_id" value="'.esc_attr($id).'">';self::field('name_de','Angebotsname Deutsch',$o['product_name']['de']??'');self::field('name_en','Angebotsname Englisch',$o['product_name']['en']??'');echo '<label>Stellplatzart<select name="parking_type">';foreach(Products::parking_types()as $type)echo '<option value="'.esc_attr($type).'" '.selected($o['parking_type']??'',$type,false).'>'.esc_html(array('outdoor'=>'Außenstellplatz','covered'=>'Überdachter Stellplatz','garage'=>'Parkhaus','underground'=>'Tiefgarage','unspecified'=>'Nicht angegeben')[$type]).'</option>';echo '</select></label>';
        foreach(array('de','en')as $lang){echo '<label>Merkmale '.strtoupper($lang).' (eine Zeile pro Merkmal)<textarea name="attributes_'.$lang.'">'.esc_textarea(implode("\n",array_map(function($a)use($lang){return Products::label($a,$lang);},$o['attributes']??array()))).'</textarea></label>';}
        foreach(array('wash'=>'Fahrzeugwäsche','charging'=>'Ladepaket','refuelling'=>'Betankungspaket','custom1'=>'Eigene Leistung 1','custom2'=>'Eigene Leistung 2')as $code=>$label){$a=array();foreach($o['addons']??array()as $item)if($item['id']===$code)$a=$item;echo '<details><summary>'.esc_html($label).'</summary><label><input type="checkbox" name="addons['.$code.'][enabled]" '.checked((bool)$a,true,false).'> Verfügbar für dieses Angebot</label>';foreach(array('de','en')as $lang){self::field('addons['.$code.'][label_'.$lang.']','Bezeichnung '.strtoupper($lang),Products::label($a['label']??'',$lang));self::field('addons['.$code.'][description_'.$lang.']','Leistungsumfang '.strtoupper($lang),Products::label($a['description']??'',$lang));}self::field('addons['.$code.'][unit_amount_cents]','Preis je Paket/Einheit (Cent)',$a['unit_amount_cents']??0,'number');self::field('addons['.$code.'][max_quantity]','Maximale Menge',$a['max_quantity']??1,'number');echo '</details>';}
        echo '<button>Angebot und Extras speichern</button></form></section><section id="prices"><h2>Preisverwaltung</h2><p>Centbeträge einschließlich Steuern. Preis je angefangene 24 Stunden oder fest je Aufenthalt. Saisonpreise ersetzen den Tagespreis für den jeweiligen örtlichen Tag des 24-Stunden-Abschnitts. Exakte Aufenthaltsdauerpreise haben Vorrang. Der höchste passende Aufenthaltsrabatt gilt; keine Kombination mehrerer Rabatte. Servicegebühren und Nachtzuschläge folgen danach. Plattformgutscheine werden separat finanziert.</p>';
        foreach($catalogue as $key=>$r){if($r['partner_id']!==$partner)continue;global $wpdb;$rate=$wpdb->get_row($wpdb->prepare('SELECT * FROM '.DB::table('rates').' WHERE partner_id=%d AND product_id=%s',$partner,$key),ARRAY_A);echo '<section><h3>'.esc_html(Products::label($r['offer']['product_name'])).'</h3><a href="'.esc_url(add_query_arg('product',$key)).'">Angebot bearbeiten</a>';self::form('rate',$partner);echo '<input type="hidden" name="product_id" value="'.esc_attr($key).'">';self::field('price_cents','Parkpreis (Cent)',$rate['price_cents']??0,'number');echo '<label>Berechnung<select name="pricing"><option value="stay" '.selected($rate['pricing']??'','stay',false).'>Fest für den Aufenthalt</option><option value="24h" '.selected($rate['pricing']??'','24h',false).'>Je angefangene 24 Stunden</option></select></label><label><input type="checkbox" name="enabled" '.checked(!empty($rate['enabled']),true,false).'> Tarif bewusst freigeben</label>';self::tariff_rules($rate?:array());echo '<button>Tarif speichern</button></form></section>';}
        echo '</section>';
    }
}
